//! 🫴️ Actual finite Source ownership survives recipient close denial and a recorded child unwind.
use semio_framework_value_native_decoding::*;
use semio_framework_value_retirement::{ErasedSnapshotRetirement,OriginalRetirementFailure,OriginalRetirementPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
struct Parent{recipient:NativeDecodeRetirementRecipient}
impl OriginalEffectProducer for Parent{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=() where 'b:'a;fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,_:&mut (),effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{self.recipient.close_into(effect,reply)}fn recover<'r,'a,'b>(&mut self,_:&mut (),effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{self.recipient.recover_close_into(effect,reply)}}
fn bank()->EffectBank{EffectBank::new(Wallet::from_profile(&serde_json::json!({"items":16,"copyBytes":4096,"capacityBytes":4096,"releaseBytes":4096,"depth":8,"fuel":8})))}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn completed(parent:&mut OriginalEffectAuthority<Parent>,action:&mut Option<OriginalEffectAction<RetainedCloneStep,OriginalRetirementFailure>>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll<RetainedCloneStep,OriginalRetirementFailure>{let before=effect.performed_work();assert!(parent.drive(&mut (),effect,action).unwrap());let mut output=None;assert!(action.as_mut().unwrap().transfer_reply(&mut output).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:output.take().unwrap(),work:effect.performed_work()-before})}
#[test]fn denied_reserved_close_keeps_the_original_recipient_and_work(){let cases:serde_json::Value=serde_json::from_str(include_str!("borrowed-close.json")).unwrap();let denied_law=&cases[2];let admitted_law=&cases[3];assert!(!denied_law["changed"].as_bool().unwrap()&&admitted_law["changed"].as_bool().unwrap());let mut recipient=NativeDecodeRetirementRecipient::new();recipient.reserve().unwrap();let mut owner=OriginalEffectAuthority::new(Parent{recipient});let mut wallet=bank();let mut action=None;let demand=owner.inspect(|p|p.recipient.next_demand(4096).unwrap());let mut denied=grant(demand);denied.maximum_copy_bytes=0;let(poll,actual)=wallet.run(denied,denied_law["remaining"].as_u64().unwrap(),|effect|completed(&mut owner,&mut action,effect));assert!(matches!(poll,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(p)),work:0}) if p==Default::default()));assert_eq!(actual,None);assert!(owner.inspect(|p|p.recipient.is_reserved()));assert_eq!(wallet.take_admitted(),None);owner.finish(&mut action).unwrap();let allowed=grant(demand);let(poll,actual)=wallet.run(allowed,admitted_law["remaining"].as_u64().unwrap(),|effect|completed(&mut owner,&mut action,effect));let RetainedWorkPoll::Complete(turn)=poll else{panic!("original funded close pending")};let progress=turn.result.unwrap().progress();assert_eq!(turn.work,1);assert_eq!(actual,None);wallet.post(progress,allowed,(0,0));assert_eq!(wallet.take_admitted(),Some(true));owner.finish(&mut action).unwrap();let parent=owner.into_producer().ok().unwrap();assert!(parent.recipient.terminal_is_empty());}
struct Child{error:Option<ValueError>,calls:Arc<AtomicUsize>,recoveries:Arc<AtomicUsize>}
impl ErasedSnapshotRetirement for Child{fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}fn next_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{depth:1,..Default::default()})}fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(1)}fn terminal_is_empty(&self)->bool{self.error.is_none()}fn close_step(&mut self,_:&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll{panic!("child close requires the original borrowed reply")}fn close_into<'r>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.calls.fetch_add(1,Ordering::SeqCst);assert!(effect.performed(1)?);reply.complete(Err(self.error.take().unwrap().into()));panic!("original child unwinds after recording its refusal")}fn recover_close_into<'r>(&mut self,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.recoveries.fetch_add(1,Ordering::SeqCst);Ok(reply.pending())}}
#[test]fn recipient_recovers_actual_child_refusal_without_replay(){let calls=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let error=ValueError::new(ValueRefusalKind::Canceled,"actual recipient child refusal".to_owned());let pointer=error.message.as_ptr();let mut recipient=NativeDecodeRetirementRecipient::new();recipient.reserve().unwrap();recipient.settle(Some(Box::new(Child{error:Some(error),calls:calls.clone(),recoveries:recoveries.clone()})));let mut owner=OriginalEffectAuthority::new(Parent{recipient});let mut wallet=bank();let mut action=None;let demand=owner.inspect(|p|p.recipient.next_demand(4096).unwrap());let admitted=grant(demand);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||wallet.run::<RetainedCloneStep,OriginalRetirementFailure>(admitted,1,|effect|completed(&mut owner,&mut action,effect))));assert!(interrupted.is_err());assert_eq!(calls.load(Ordering::SeqCst),1);let(poll,actual)=wallet.run(admitted,1,|effect|completed(&mut owner,&mut action,effect));let RetainedWorkPoll::Complete(turn)=poll else{panic!("original child refusal remains pending")};assert_eq!(turn.work,0);assert_eq!(actual,None);let failure=turn.result.unwrap_err();assert_eq!(failure.primary().unwrap().message.as_ptr(),pointer);assert_eq!(wallet.take_admitted(),Some(true));owner.finish(&mut action).unwrap();let demand=owner.inspect(|p|p.recipient.next_demand(4096).unwrap());let admitted=grant(demand);let((poll,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||wallet.run(admitted,1,|effect|completed(&mut owner,&mut action,effect)));let RetainedWorkPoll::Complete(turn)=poll else{panic!("original child shell close pending")};assert_eq!(actual,None);wallet.post(turn.result.unwrap().progress(),admitted,heap);assert_eq!(wallet.take_admitted(),Some(true));owner.finish(&mut action).unwrap();assert_eq!(calls.load(Ordering::SeqCst),1);assert_eq!(recoveries.load(Ordering::SeqCst),0);let parent=owner.into_producer().ok().unwrap();assert!(parent.recipient.terminal_is_empty());drop(failure);}
